let register check check_tree result =
  let valid, extra_info, stats, models, manual, unproved_status =
    match result with
    | Proved (stats, stats_checker) ->
        true,
        {Gnat_expl.pretty_node = None; inlined = None},
        Some (stats, stats_checker),
        [],
        None,
        Gnat_expl.Unknown
    | Not_Proved (extra_info, models, manual, unproved_status) ->
        false, extra_info, None, models, manual, unproved_status
  in
  if (Gnat_expl.HCheck.mem msg_set check) then assert false
  else begin
    let stats_g = Option.map (fun x -> let (stats, _) = x in stats) stats in
    let stats_checker = Option.map (fun x -> let (_, sc) = x in sc) stats in
    let msg =
    { result         = valid;
      extra_info     = extra_info;
      stats          = adapt_stats stats_g;
      stats_checker  = Option.value ~default:0 stats_checker;
      check_tree     = check_tree;
      cntexmp_models = models;
      manual_proof   = manual;
      unproved_status = unproved_status } in
    Gnat_expl.HCheck.add msg_set check msg

  | Some (fname, cmd) ->
      [ "vc_file", String (Sys.getcwd () ^ Filename.dir_sep ^ fname);
        "editor_cmd", String cmd
      ]

let get_prover_stats stat =
  Record [
    "count", Int stat.count;
    "max_steps", Int stat.max_steps;
    "max_time", StandardFloat stat.max_time
  ]

let get_stats (stats, stat_checker) =
  (* Compute the stats for goal solved by transformations as a fake prover. *)
  let fake_prover_ch =
    Whyconf.{prover_name = "Checker"; prover_version = ""; prover_altern = ""}
  in
  match stats with
  | None -> []
  | Some s ->
    if stat_checker <> 0 then
      Whyconf.Hprover.add s fake_prover_ch
        {count = stat_checker; max_steps = 0; max_time = 0.0};
    let kv_list = Whyconf.Hprover.fold (fun k v acc -> (k,v)::acc) s [] in
    let get_name pr = pr.Whyconf.prover_name in
    [ "stats",
      Record (List.map (fun (k,v) -> get_name k, get_prover_stats v) kv_list) ]

let opt_int i = Option.value ~default:0 i

let get_extra_info i =
  match i with
  | { Gnat_expl.pretty_node = i; inlined = inline } ->
      Record [
        "node", Int (opt_int i);
        "inline", Int (opt_int inline)
      ]

let get_unproved_status status =
  let status, time, steps, memory =
    match status with
    | Gnat_expl.Unknown ->
        "unknown", false, false, false
    | Gnat_expl.Gave_up ->
        "gave_up", false, false, false
    | Gnat_expl.Limit { timeout; step; memory } ->
        "limit", timeout, step, memory
  in
  Record [
    "status", String status;
    "time", Bool time;
    "steps", Bool steps;
    "memory", Bool memory
  ]

let get_msg (check, m) =
  Record (
    List.concat [
      [ "id", Int check.Gnat_expl.id ;
        "check_kind", String (Gnat_expl.check_kind_to_ada check.Gnat_expl.check_kind) ;
        "result", Bool m.result ;
        "check_tree", m.check_tree ;
        "extra_info", get_extra_info m.extra_info ;
        "unproved_status", get_unproved_status m.unproved_status
      ] ;
      get_stats (m.stats, m.stats_checker);
      ["cntexmps", List (get_cntexmp_models m.cntexmp_models)];
      get_manual_proof_info m.manual_proof
    ]
  )

(* In case several models are returned by Why3, we sort them by id. *)
let sort_messages (l : (Gnat_expl.check * msg) list) =
  List.sort (fun x y -> compare (fst x).Gnat_expl.id (fst y).Gnat_expl.id) l

let get_results () =
  let msg_set =
    Gnat_expl.HCheck.fold (fun k v acc -> (k,v) :: acc) msg_set []
  in
  "results", List (List.map get_msg (sort_messages msg_set))

let get_warnings () =
  match !warning_list with
  | [] -> []
  | l -> [("warnings", List (List.map (fun elem -> String elem) l))]

let get_timings () =
  let l = Hashtbl.fold (fun k v acc -> (k,v)::acc) (Debug.Stats.get_timings ()) [] in
  let get_name s = s in
  "timings", Record (List.map (fun (k,(v,_n)) -> get_name k, StandardFloat v) l)

let get_entity () =
  "entity", Int Gnat_config.entity

(* The main function, where we build the final Record to be printed using
Why3.Json_base.print_json function. *)
let print_messages () =
  print_json_single_line Format.std_formatter (
    Record (
      List.concat [
        [get_results (); get_timings (); get_entity ()];
        get_warnings ()
      ]
    )
  )

let rec check_to_json session check =
  let check_rec = Gnat_expl.HCheck.find explmap check in
  let l = ref [] in
  GoalSet.iter (fun x -> l := goal_to_json session x :: !l) check_rec.toplevel;
  Json_base.List !l
and goal_to_json session g =
  Json_base.Record [
    "proof_attempts", proof_attempts_to_json session g;
    "transformations", transformations_to_json session g;
  ]
and proof_attempts_to_json session g =
  let aux prover paid acc =
    let pa = Session_itp.get_proof_attempt_node session paid in
    let pr_name = prover.Whyconf.prover_name in
    match pa.Session_itp.proof_obsolete, pa.Session_itp.proof_state with
    | false, Some pr ->
        (pr_name, proof_result_to_json pr_name pr) :: acc
    | _, _ -> acc in
  let pas = Session_itp.get_proof_attempt_ids session g in
  Json_base.Record (Whyconf.Hprover.fold aux pas [])

and proof_result_to_json prover r =
  let answer =
    Pp.sprintf "%a"
      Call_provers.print_prover_answer r.Call_provers.pr_answer in
  let steps =
    Gnat_config.back_convert_steps ~prover r.Call_provers.pr_steps in
  Json_base.Record [
    "time", Json_base.Float r.Call_provers.pr_time;
    "steps", Json_base.Int steps;
    "result", Json_base.String answer;
  ]
and transformations_to_json session g =
  let aux tfid =
    let tf_name = Session_itp.get_transf_name session tfid in
    tf_name, transformation_to_json session tfid in
  Json_base.Record (List.map aux (Session_itp.get_transformations session g))
and transformation_to_json session tf =
  let transf_goals = Session_itp.get_sub_tasks session tf in
  Json_base.List (List.map (goal_to_json session) transf_goals)

open Why3
open Why3.Json_base

let abort_with_message ~internal s =
  print_json Format.std_formatter 
    (Record [ "error", String s;
              "internal", Bool internal;
              "results", List []]);
  exit 1

let () =
  Printexc.set_uncaught_exception_handler
    (fun exn raw_backtrace ->
       let bt = Printexc.raw_backtrace_to_string raw_backtrace in
       let msg = Format.asprintf "%a\nBacktrace is the following:\n%s@."
           Why3.Exn_printer.exn_printer exn bt
       in
       let internal =
         match exn with
         | Out_of_memory -> false
         | _ -> true in
       abort_with_message ~internal msg)

let compute_tag output tag_acc =
  let buf = Buffer.create 16 in
  let ppf = formatter_of_buffer buf in
  output ppf tag_acc;
  pp_print_flush ppf ();
  let len = Buffer.length buf in
  if len < 2 then Buffer.contents buf
  else Buffer.sub buf 1 (len - 2)
